func TestRestoreRejectsSettledAtOrAfterReserveDeadline(t *testing.T) {
	t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)

	for _, approved := range []bool{false, true} {

package wallet

import (
